// 真实 Node 里没有 advance，因为事件循环自己转；这里对应的是：
//   下一轮 tick  = setImmediate
//   微任务       = process.nextTick / Promise.then
const cache = new Map()
function get(key, load) {
  if (cache.has(key)) return Promise.resolve(cache.get(key))
  return load(key).then((v) => { cache.set(key, v); return v })
}
// 这个 then 回调和 nextTick 注册的回调，谁先跑取决于上面的两级队列

