// asyncio 里对应的三件套：
//   spawn(genFn)  ≈ asyncio.create_task(coro)
//   step()        ≈ loop._run_once() 里的一次回调
//   yield {wait}   ≈ await asyncio.sleep(ms)
//   run()         ≈ await asyncio.gather(*tasks)
async def handler():
    data = await fetch()      # 这里让出执行权，别的请求继续跑
    return await render(data)

stages.code:
function createRunner() {
  const tasks = []
  const ready = []
  let seq = 0

  return {
    spawn(genFn) {
      const t = { id: ++seq, gen: genFn(), done: false, value: undefined, error: null }
      tasks.push(t)
      ready.push(t)
      return t
    },
    step() {
      const t = ready.shift()
      if (!t) return null
      const r = t.gen.next()
      if (r.done) {
        t.done = true
        t.value = r.value
      } else {
        ready.push(t)
      }
      return t.id
    }
  }
}

stages.test:
{
  check('spawn 不立即执行，step 才推进一步', () => {
    const order = []
    const r = createRunner()
    const t = r.spawn(function* () { order.push('a'); yield; order.push('b') })
    same(order, [], 'spawn 只是登记，不该执行协程体')
    same(r.step(), t.id)
    same(order, ['a'])
  })
  check('多个任务按 spawn 顺序轮转，yield 后回到队尾', () => {
    const order = []
    const r = createRunner()
    r.spawn(function* () { order.push('a1'); yield; order.push('a2') })
    r.spawn(function* () { order.push('b1'); yield; order.push('b2') })
    r.step(); r.step()
    same(order, ['a1', 'b1'])
    r.step(); r.step()
    same(order, ['a1', 'b1', 'a2', 'b2'], 'yield 后重新排队，不会一直占着执行权')
  })
  check('一个任务要多次 step 才能跑完', () => {
    const order = []
    const r = createRunner()
    r.spawn(function* () { order.push(1); yield; order.push(2); yield; order.push(3) })
    r.step()
    same(order, [1])
    r.step()
    same(order, [1, 2])
  })
  check('就绪队列空了 step 返回 null', () => {
    const r = createRunner()
    r.spawn(function* () { return 'ok' })
    same(r.step(), 1)
    same(r.step(), null)
  })
}

