function createRunner() {
  const tasks = []
  const ready = []
  let seq = 0

  return {
    spawn(genFn) {
      const t = { id: ++seq, gen: genFn(), done: false, value: undefined, error: null }
      tasks.push(t)
      ready.push(t)
      return t
    },
    step() {
      const t = ready.shift()
      if (!t) return null
      const r = t.gen.next()
      if (r.done) {
        t.done = true
        t.value = r.value
      } else {
        ready.push(t)
      }
      return t.id
    },
    run() {
      while (ready.length) this.step()
      return tasks.map((t) => ({ id: t.id, done: t.done, value: t.value, error: t.error }))
