{
  check('run 把所有任务跑到完成，并按 spawn 顺序返回结果', () => {
    const r = createRunner()
    r.spawn(function* () { yield; return 'a' })
    r.spawn(function* () { return 'b' })
    const out = r.run()
    same(out.map((x) => x.value), ['a', 'b'], '结果按 spawn 顺序，不是完成顺序')
