  })
  check('已完成的任务不会再执行第二次', () => {
    let runs = 0
    const r = createRunner()
    r.spawn(function* () { runs++ })
    r.run()
    same(runs, 1)
    same(r.run().length, 1, '再次 run 只是回放结果，不重跑')
  })
  check('多个多步任务交替推进', () => {
    const order = []
    const r = createRunner()
    r.spawn(function* () { order.push('a1'); yield; order.push('a2') })
    r.spawn(function* () { order.push('b1'); yield; order.push('b2') })
